"use client";
import { useState } from "react";

export function CopyLink({ url }: { url: string }) {
  const [copied, setCopied] = useState(false);
  return (
    <div className="mt-2 flex flex-wrap items-center gap-2">
      <a href={url} target="_blank" rel="noreferrer" className="min-w-0 truncate rounded-lg bg-paper px-3 py-2 text-[15px] font-semibold text-brand-deep">{url}</a>
      <button type="button" className="min-h-10 rounded-lg px-3 text-[15px] font-semibold ring-1 ring-line hover:bg-paper"
        onClick={async () => { try { await navigator.clipboard.writeText(url); setCopied(true); setTimeout(() => setCopied(false), 2000); } catch {} }}>
        {copied ? "Copied" : "Copy link"}
      </button>
    </div>
  );
}
